// ❌ OLD: One page per URL. To show feed + analytics together you
// compose them inside a single page component, so they cannot navigate
// independently and any navigation reloads the whole composition.
import { Feed } from '@/components/feed';
import { Analytics } from '@/components/analytics';

export default function DashboardPage() {
  return (
    <div>
      {/* ❌ OLD: both sections are hard-wired into one route */}
      <Feed />
      <Analytics />
    </div>
  );
}

// Navigating to /dashboard/analytics would need a different page; you
// cannot keep the feed mounted while only the analytics section changes.

// ✅ NEW: Parallel routes. Each @slot is an independent page tree
// rendered into its named outlet; sections navigate independently.
// app/@feed/page.tsx and app/@analytics/page.tsx exist as separate
// route trees.
export default function DashboardLayout(props: {
  children: React.ReactNode;
  feed: React.ReactNode; // ✅ NEW: the @feed slot
  analytics: React.ReactNode; // ✅ NEW: the @analytics slot
}) {
  return (
    <div className="dashboard">
      <aside>{props.feed}</aside> {/* ✅ NEW: renders @feed/page.tsx */}
      <main>{props.children}</main>
      <aside>{props.analytics}</aside> {/* ✅ NEW: renders @analytics/page.tsx */}
    </div>
  );
}

// Navigation updates only the affected slot; unmatched slots use
// their default.tsx fallback.
